import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"Weight-space structure hypothesis: falsified","description":"","frontmatter":{"title":"Weight-space structure hypothesis: falsified","type":"adr","date":"2025-09","status":"rejected","status_note":"decided (negative) — closed."},"headers":[],"relativePath":"graphopt/project/adrs/0001-weight-space-structure-falsified.md","filePath":"vendored/graphopt/project/adrs/0001-weight-space-structure-falsified.md"}`),a={name:`graphopt/project/adrs/0001-weight-space-structure-falsified.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="adr-0001-—-weight-space-structure-hypothesis-falsified" tabindex="-1">ADR 0001 — Weight-space structure hypothesis: falsified <a class="header-anchor" href="#adr-0001-—-weight-space-structure-hypothesis-falsified" aria-label="Permalink to “ADR 0001 — Weight-space structure hypothesis: falsified”">​</a></h1><p><strong>Date</strong>: 2025-09 (measured on stories15M + stories110M, llama2.c)</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to “Context”">​</a></h2><p>The motivating extension of catopt: treat the weight file as a program. If trained weights hid exact structure (duplicates, subspaces, symmetries, generators), catopt&#39;s equivalence machinery could shrink storage <em>losslessly</em> — a genuinely new capability.</p><h2 id="what-was-measured" tabindex="-1">What was measured <a class="header-anchor" href="#what-was-measured" aria-label="Permalink to “What was measured”">​</a></h2><p>Every hypothesis class for exact structure in trained checkpoints:</p><table tabindex="0"><thead><tr><th>probe</th><th>hypothesis</th><th>result</th></tr></thead><tbody><tr><td>Phase 0</td><td>Toeplitz / displacement rank</td><td>full rank — dead</td></tr><tr><td>Phase 0b</td><td>H-matrix, sparse, monarch/butterfly, INR manifold</td><td>dead or inconclusive; Kronecker-sum beat SVD 15–31% but…</td></tr><tr><td>Phase 5</td><td><strong>real perplexity</strong> (TinyStories, baseline 5.03)</td><td>structural compression kills quality at every rank (r192/288 → ppl 214); only int8 RTN survives (4×, ppl 5.16)</td></tr><tr><td>Relational</td><td>cross-layer bitwise dups / shared subspace / Procrustes alignment</td><td><strong>0 hits, full column rank, 0 aligned</strong> on both checkpoints</td></tr><tr><td>Symmetry</td><td>equivariance <code>WG=GW</code> (cyclic/dihedral/block)</td><td>resid ≈ √2 — no symmetry</td></tr><tr><td>Polynomial</td><td>low-degree <code>p(W)=0</code></td><td>minimal poly = full degree (288 distinct eigenvalues)</td></tr><tr><td>Learned displacement</td><td>rank(<code>AW−WB</code>) over structured A,B</td><td>disp-rank ~280/288 — full</td></tr></tbody></table><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><p><strong>The door is closed.</strong> Trained checkpoint weights are information-dense at the bit level — no emergent exact structure exists to exploit. The ε axis (bounded-error rewrites) survives as an optional toolkit where a norm bound IS the contract (activation paths, verification), but Phase 5 showed norm bounds don&#39;t predict task quality — approximate structure ≠ quality-preserving.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><ul><li>catopt&#39;s value is <strong>graph-level</strong>: semantic carriers, non-local pairing, omd executor, certificates — not weight compression.</li><li>The exact corner that survives is architectural: tying, materialized GQA replication, dead params (measured 0–75% by archetype).</li><li>README headline and claims now reflect this scope.</li></ul>`,11)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};